def run(fasta: str, hits_path: str, out_fasta: str, report: str, summary: str, min_len: int = DEFAULT_MIN_LEN) -> Dict: hits = read_hits(hits_path) counts = defaultdict(int) with open_any(out_fasta, "wt") as fo, open(report, "w") as fr: fr.write("accession	qlen	action	kept	categories
") for acc, rest, seq in read_fasta(fasta): qlen = len(seq) action, pieces, tags = plan_record(qlen, hits.get(acc, []), min_len) if acc in hits else ("keep", [(1, qlen)], []) if action == "keep" and qlen < min_len: action, pieces = "drop", [] counts[action] += 1 counts["bases_in"] += qlen for i, (a, b) in enumerate(pieces, 1): name = acc if len(pieces) == 1 else f"{acc}_part{i}" fo.write(f">{name} {rest} univec={action}:{a}-{b}/{qlen}
" if rest else f">{name} univec={action}:{a}-{b}/{qlen}
") fo.write(seq[a - 1:b] + "
") counts["bases_out"] += b - a + 1 counts["records_out"] += 1 fr.write(f"{acc}	{qlen}	{action}	{';'.join(f'{a}-{b}' for a, b in pieces)}	{';'.join(tags)}
") counts["records_in"] = counts["keep"] + counts["trim"] + counts["split"] + counts["drop"] with open(summary, "w") as fs: json.dump(dict(counts), fs, indent=1) return dict(counts)

def main(argv: Optional[List[str]] = None) -> int: ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter) ap.add_argument("--fasta", required=True, help="partitioned OrthoDB FASTA (.gz)") ap.add_argument("--out-dir", required=True) ap.add_argument("--exclude-taxid", type=int, nargs="+", default=[3702, 4577, 4081], help="evaluated species (A19.1)") ap.add_argument("--lineage", help="taxid<TAB>lineage TSV (cache for --fetch-lineage)") ap.add_argument("--fetch-lineage", action="store_true", help="fetch missing lineages from NCBI E-utilities into --lineage") ap.add_argument("--allow-missing-lineage", action="store_true") ap.add_argument("--exclude-proteome", action="append", default=[], help="SPECIES=<protein FASTA>: drop identical sequences (repeatable)") a = ap.parse_args(argv) os.makedirs(a.out_dir, exist_ok=True) present: Counter = Counter() for name, _ in read_fasta(a.fasta): present[taxid_of_header(name)] += 1 lineage = read_lineage(a.lineage) if a.lineage and os.path.exists(a.lineage) else {} if a.fetch_lineage: if not a.lineage: raise SystemExit("--fetch-lineage needs --lineage <cache path>") lineage = fetch_lineage(present.keys(), a.lineage) drop_taxids = excluded_taxids(set(a.exclude_taxid), lineage, set(present), a.allow_missing_lineage) exclude_seqs: Dict[str, Set[str]] = {} for sp, path in _parse_kv(a.exclude_proteome).items(): exclude_seqs[sp] = {s.rstrip("*").upper() for _, s in read_fasta(path)} out_fa = os.path.join(a.out_dir, "odb12_Viridiplantae.filtered.fa.gz") kept: Counter = Counter() removed_taxid = 0 removed_exact: Counter = Counter() with gzip.open(out_fa, "wt") as out: for name, seq in read_fasta(a.fasta): tid = taxid_of_header(name) if tid in drop_taxids: removed_taxid += 1 continue s = seq.rstrip("*").upper() hit = next((sp for sp, ss in exclude_seqs.items() if s in ss), None) if hit: removed_exact[hit] += 1 continue kept[tid] += 1 out.write(f">{name}
") for i in range(0, len(seq), 60): out.write(seq[i:i + 60] + "
") with open(os.path.join(a.out_dir, "counts_by_taxid.tsv"), "w") as fh: fh.write("taxid	sequences_in	sequences_out	excluded_by_lineage
") for tid, n in sorted(present.items()): fh.write(f"{tid}	{n}	{kept.get(tid, 0)}	{int(tid in drop_taxids)}
") summary = {"input": os.path.abspath(a.fasta), "input_md5": file_md5(a.fasta), "output": out_fa, "output_md5": file_md5(out_fa), "sequences_in": sum(present.values()), "sequences_out": sum(kept.values()), "taxids_in": len(present), "taxids_out": len(kept), "exclude_taxid": sorted(a.exclude_taxid), "excluded_taxids": sorted(drop_taxids), "removed_by_taxid": removed_taxid, "removed_by_exact_match": dict(removed_exact), "exclude_proteomes": _parse_kv(a.exclude_proteome), "lineage_source": a.lineage or "", "date": time.strftime("%Y-%m-%dT%H:%M:%S%z")} with open(os.path.join(a.out_dir, "filter_summary.json"), "w") as fh: json.dump(summary, fh, indent=2) print(json.dumps({k: summary[k] for k in ("sequences_in", "sequences_out", "taxids_in", "taxids_out", "removed_by_taxid", "removed_by_exact_match", "excluded_taxids")})) return 0

def stream(gff, blocks_fh, introns_fh, alignments_fh): """One pass. Emits one row per alignment, plus its CDS blocks and introns when accepted. Block and intron rows carry the protein id as a trailing column: ambiguity is only known once every alignment of a protein has been seen, so the rows are filtered afterwards (see filter_ambiguous).""" paf = None cur = None # (mrna_id, attrs, score, chrom, strand) cds = [] per_protein = defaultdict(list) # protein -> [(score, accepted, key)] stats = defaultdict(int) rejected = defaultdict(int) def flush(): nonlocal cur, cds if cur is None: return mid, attrs, score, chrom, strand = cur target = attrs.get("Target", "").split() prot = target[0] if target else "" if paf is None or paf["qname"] != prot: raise SystemExit(f"REFUSED: {mid} has no matching ##PAF record (got {paf and paf['qname']!r}, want {prot!r})") org = organism_of(prot) ok, reasons, introns, identity, coverage = judge(paf, attrs, cds) stats["alignments"] += 1 stats["accepted"] += int(ok) for r in reasons: rejected[r] += 1 per_protein[prot].append((score, ok, (chrom, cds[0][0] if cds else 0, strand))) alignments_fh.write(f"{mid}	{prot}	{org}	{chrom}	{strand}	{score}	" f"{identity:.4f}	{coverage:.4f}	{paf['fs']}	{len(cds)}	" f"{'accepted' if ok else 'rejected'}	{','.join(reasons) or '.'}
") if ok: for s, e in sorted(cds): blocks_fh.write(f"{chrom}	{s}	{e}	{org}	{prot}
") for s, e, d, a in introns: introns_fh.write(f"{chrom}	{s}	{e}	{strand}	{d}-{a}	{org}	{prot}
") cur, cds = None, [] with _open(gff) as fh: for line in fh: if line.startswith("##PAF	"): flush() paf = parse_paf(line) continue if line.startswith("#"): continue f = line.rstrip("
").split("	") if len(f) < 9: continue if f[2] == "mRNA": flush() attrs = dict(ATTR.findall(f[8])) cur = (attrs.get("ID", ""), attrs, int(f[5]), f[0], f[6]) elif f[2] == "CDS" and cur is not None: cds.append((int(f[3]), int(f[4]))) flush() return per_protein, stats, rejected

def flush(): nonlocal cur, cds if cur is None: return mid, attrs, score, chrom, strand = cur target = attrs.get("Target", "").split() prot = target[0] if target else "" if paf is None or paf["qname"] != prot: raise SystemExit(f"REFUSED: {mid} has no matching ##PAF record (got {paf and paf['qname']!r}, want {prot!r})") org = organism_of(prot) ok, reasons, introns, identity, coverage = judge(paf, attrs, cds) stats["alignments"] += 1 stats["accepted"] += int(ok) for r in reasons: rejected[r] += 1 per_protein[prot].append((score, ok, (chrom, cds[0][0] if cds else 0, strand))) alignments_fh.write(f"{mid}	{prot}	{org}	{chrom}	{strand}	{score}	" f"{identity:.4f}	{coverage:.4f}	{paf['fs']}	{len(cds)}	" f"{'accepted' if ok else 'rejected'}	{','.join(reasons) or '.'}
") if ok: for s, e in sorted(cds): blocks_fh.write(f"{chrom}	{s}	{e}	{org}	{prot}
") for s, e, d, a in introns: introns_fh.write(f"{chrom}	{s}	{e}	{strand}	{d}-{a}	{org}	{prot}
") cur, cds = None, []

def audit_from_sam(sam, gff, out, run, dataset, key): """Legacy scorer accepts arbitrary output root; retain four-field DONE key.""" if (out / 'audit.json').exists() or (out / 'DONE').exists(): raise ValueError('refuse overwriting orientation artifact') cmd = [sys.executable, str(SCRIPTS / '67_orientation_audit.py'), '--sam', str(sam), '--gff', str(gff), '--out', str(out / 'audit.json'), '--run', run, '--species', 'Athaliana', '--dataset', dataset] with (out / 'audit.stdout').open('x') as stdout, (out / 'audit.stderr').open('x') as stderr: rc = subprocess.run(cmd, stdout=stdout, stderr=stderr).returncode if rc not in (0, 4): raise ValueError(f'orientation scorer failed: {rc}') marker = f'key={key}
run={run}
audit_md5={digest(out / "audit.json")}
' (out / 'DONE.tmp').write_text(marker) (out / 'DONE.tmp').rename(out / 'DONE') return read_audit(out, key, run)

