def test_awk_programs_avoid_interval_expressions(): """`/x{32}/` matches nothing under POSIX awk and older mawk, silently. The gate used /^[[:xdigit:]]{32}$/ to validate an md5. mawk 1.3.4 on pronghorn matches it; the awk on pgl-gpu does not, so every md5 read as invalid and the gate refused a correct manifest — found 2026-09-05 when the A40 pre-flight ran the suite on the GPU host. The failure direction was safe, but ACCESS staging would have been blocked on that machine with a message accusing the manifest. A test cannot easily run two awks, so it pins the rule instead: no interval expressions in the awk programs of this script. Use length() plus a character class. """ import re # Comments explain the trap and quote the bad pattern, so they must not be scanned. code = "
".join(l for l in SCRIPT.read_text().splitlines() if not l.lstrip().startswith("#")) offenders = [m.group(0) for m in re.finditer(r"/\^?\[?\[:[a-z]+:\]\]?[^/
]*\{\d+(,\d*)?\}[^/
]*/", code)] assert not offenders, f"awk interval expression is not portable: {offenders}"

class FakeRemote: """A fake ssh_run + fetch + push trio that share enough state to make the checksum-verification round trips in `fetch_and_verify`/`push_and_verify` self-consistent: `fetch()`/`push()` really register the local file, and the `md5sum <remote>` ssh branch reports that same file's real md5 back — exactly what a real host would report after a real rsync, so tests never hand-compute a hash. `gff_rows_by_hint`: {substring-of-remote-path: rows} — picks which fixture rows to write for a given remote *output* path. A fetched output path matching no hint raises, so an unexpected fetch fails the test instead of silently succeeding. (Input subset pushes are not looked up this way — the pushed file already has real content, written by `build_local_subset` before the push ever happens.) `fail_hints`: remote commands containing any of these substrings get a nonzero return code instead of the canned success response (simulates a remote crash for that one chunk, or one specific step, without touching the others). `host_commit`: what `git rev-parse HEAD` reports; defaults to the pinned commit gpu-environment.md verifies reproduces the published benchmark. """ def __init__(self, gff_rows_by_hint, fail_hints=(), log_text="Output written to: out.gff3
", prompt_stdout="Output written to: out.gff3
", host_commit=None): self.gff_rows_by_hint = gff_rows_by_hint self.fail_hints = tuple(fail_hints) self.log_text = log_text self.prompt_stdout = prompt_stdout self.host_commit = host_commit or run_bench.EXPECTED_HOST_COMMIT self._written = {} def ssh_run(self, argv): cmd = argv[-1] if cmd.startswith("md5sum "): remote_path = cmd[len("md5sum "):].strip() local_path = self._written.get(remote_path) if local_path is None or not local_path.exists(): return FakeCompletedProcess(returncode=1, stderr=f"no such file: {remote_path}") return FakeCompletedProcess(returncode=0, stdout=f"{run_bench.md5_file(local_path)} {remote_path}
") if cmd.endswith("git rev-parse HEAD"): return FakeCompletedProcess(returncode=0, stdout=f"{self.host_commit}
") if any(hint in cmd for hint in self.fail_hints): return FakeCompletedProcess(returncode=1, stderr="simulated remote failure") return FakeCompletedProcess(returncode=0, stdout=self.prompt_stdout) def fetch(self, remote_path, local_path, host="gpu"): local_path.parent.mkdir(parents=True, exist_ok=True) if remote_path.endswith(".log"): local_path.write_text(self.log_text) else: rows = next((r for hint, r in self.gff_rows_by_hint.items() if hint in remote_path), None) if rows is None: raise AssertionError(f"unexpected fetch for {remote_path}") _write_gff(local_path, rows) self._written[remote_path] = local_path def push(self, local_path, remote_path, host="gpu"): # A real rsync push copies bytes to the host; here the "host" is just this # object's own bookkeeping, keyed the same way fetch() keys it, so the # subsequent md5sum branch above can find and hash the (already real) local # file build_local_subset wrote. self._written[remote_path] = local_path

