def _decide(tmp_path: Path, *, rc: int, err_before: str = "", err_after: str = "", env: dict | None = None, forced_preempt: bool = False) -> dict: """Run the decision block with a stub sbatch; return exit code, stdout, stub args/env, marker state.""" run = tmp_path / "run"; run.mkdir(exist_ok=True) if forced_preempt: (run / "FORCED_PREEMPT.1").write_text("") # job-scoped marker; the harness uses SLURM_JOB_ID=1 err = run / "train.err" err.write_text(err_before) off = err.stat().st_size with err.open("a") as fh: fh.write(err_after) binq = tmp_path / "bin"; binq.mkdir(exist_ok=True) stub = binq / "sbatch" stub.write_text('#!/bin/bash
echo "SBATCH_ARGS: $*"
echo "SBATCH_ENV_EXCLUDE: ${EXCLUDE_NODES:-<unset>}"
echo "Submitted batch job 999"
') stub.chmod(0o755) harness = "set -euo pipefail
" # the real script runs under errexit: a stray non-zero status must not end it harness += f'PATH="{binq}:$PATH"
RUN_HOST="{run}"
ERR_OFF={off}
TRAIN_RC={rc}
' harness += 'WATCHDOG=${WATCHDOG:-}
' harness += 'WORK=/w; REPO_DIR=/w/repo; SEED=456; GPUS=4; SLURM_JOB_ID=1; SLURM_NODELIST=gh121
FORCED="$RUN_HOST/FORCED_PREEMPT.$SLURM_JOB_ID"
' harness += 'CHAIN_N=${CHAIN_N:-1}; CHAIN_MAX=${CHAIN_MAX:-8}
' harness += _decision_block() out = subprocess.run(["bash", "-c", harness], capture_output=True, text=True, timeout=30, env={**{"PATH": "/usr/bin:/bin"}, **(env or {})}) return {"code": out.returncode, "out": out.stdout + out.stderr, "failed_marker": (run / "TRAINING_FAILED").exists(), "forced_marker": (run / "FORCED_PREEMPT.1").exists()}
